window.MOTIF_CATALOG_CHUNKS[32]={"cards":[{"id":"MEJE-KW-003297","row_version":2,"title":"시리즈 규칙에서 벗어난 기묘한 회차","original":"Bizarro Episode","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"한 회차가 평소의 인물 행동이나 장르, 사건의 흐름과 크게 어긋난다. 이후에 거의 언급되지 않으면 시리즈 안에서 독립된 경험처럼 남는다. 한 회차가 앞이야기와 동떨어진 기묘한 시작으로 시작할 수 있다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-003297/index.html"},{"id":"MEJE-KW-003298","row_version":2,"title":"기묘한 현실을 중심에 둔 소설","original":"Bizarro Fiction","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"꿈같은 현실과 뜻밖의 사물·사건을 자연스럽게 엮는 소설 유형. 낯섦 자체가 웃음이나 불안, 사고의 실마리가 된다. 기묘한 현실이 다른 세계와 맞물리면 익숙한 관계가 뒤집힌 평행 세계의 구도가 된다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-003298/index.html"},{"id":"MEJE-KW-003299","row_version":2,"title":"익숙한 관계가 뒤집힌 평행 세계","original":"Bizarro Universe","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"원래 세계와 닮았지만 역할이나 가치, 관계의 방향이 반대로 놓인 장소. 무엇을 뒤집고 무엇을 유지하는지가 두 세계의 차이를 만든다. 뒤집힌 세계의 건축이 불가능해 보이는 건축처럼 보일 수 있다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-003299/index.html"},{"id":"MEJE-KW-003300","row_version":2,"title":"검정과 파랑의 위협적 배색","original":"Black and Blue and Scary All Over","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"검은 바탕에 어두운 파랑을 겹쳐 차갑고 깊은 공간의 불안을 만든다. 색 자체의 고정된 뜻보다 조명과 장면의 맥락이 인상을 정한다. 검정과 노랑의 경고 배색와 달리 차가운 어둠을 강조하는 색 조합이다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003300/index.html"},{"id":"MEJE-KW-003301","row_version":2,"title":"선하지 않은 편과 더 잔혹한 편의 대립","original":"Black-and-Gray Morality","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"갈등 양쪽에 결점이 있지만 한쪽의 해악이 더 커 관객이 다른 쪽에 기대게 된다. 편을 고르는 이유와 그 편의 책임을 함께 볼 수 있다. 선과 악이 분명히 나뉜 세계의 단순한 대립을 흐리지만 모든 책임이 같은 것은 아니다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-003301/index.html"},{"id":"MEJE-KW-003302","row_version":2,"title":"흑인 괴짜·전문가 인물","original":"Black and Nerdy","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"흑인 인물을 기술이나 공부, 특정 취미에 깊이 몰두하는 사람으로 그린다. 인종에 붙여진 좁은 기대를 벗어나되 취미 하나로 인물을 전부 설명하지 않는다. 흑인 여성 책임자라는 인물 틀와 함께 흑인 인물에게 한 가지 역할만 주는지 살필 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003302/index.html"},{"id":"MEJE-KW-003303","row_version":2,"title":"선악의 이분법에 갇힌 인물","original":"Black-and-White Insanity","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 주변 사람을 오직 선하거나 악한 쪽으로만 판단해 복잡한 사정을 받아들이지 못한다. 작품은 이를 위험한 집착으로 묘사할 수 있지만 실제 정신건강의 진단과 같지는 않다. 인물의 판단과 실제 선과 악이 분명히 나뉜 세계의 구도를 분리해 본다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-003303/index.html"},{"id":"MEJE-KW-003304","row_version":2,"title":"선과 악이 분명히 나뉜 세계","original":"Black-and-White Morality","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"이야기에서 영웅 진영과 적대 진영의 가치와 행동이 뚜렷하게 갈린다. 선택의 명료함이 갈등의 힘이 되지만 각 진영의 내부 차이는 줄어들 수 있다. 두 진영의 결점이 드러나면 선하지 않은 편과 더 잔혹한 편의 대립의 갈등으로 바뀔 수 있다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-003304/index.html"},{"id":"MEJE-KW-003305","row_version":2,"title":"검정과 노랑의 경고 배색","original":"Black and Yellow and Alarming All Over","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"검은색과 노란색을 함께 써 위험이나 접근 금지의 신호를 만든다. 익숙한 표지의 인상이 인물·사물·장소로 옮겨 간다. 검정의 인상을 이용하지만 검정과 파랑의 위협적 배색와는 경고를 앞세운다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-003305/index.html"},{"id":"MEJE-KW-003306","row_version":2,"title":"검은 점으로 그린 눈","original":"Black Bead Eyes","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"눈동자와 흰자 대신 작은 검은 점으로 눈을 그려 단순한 얼굴을 만든다. 적은 선으로도 시선과 감정의 변화를 표현할 수 있다. 검은 점으로 그린 눈동자와 달리 눈 전체를 점처럼 단순화한다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003306/index.html"},{"id":"MEJE-KW-003307","row_version":1,"title":"외국어를 무술인 척 내세우기","original":"Black Belt in Origami","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 낯선 단어를 격투 기술처럼 말해 상대를 겁주려 한다. 말의 뜻을 아는 사람이 나타나면 허세가 곧바로 드러난다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-003307/index.html"},{"id":"MEJE-KW-003308","row_version":1,"title":"피의 색을 바꿔 폭력감을 낮추기","original":"Black Blood","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"작품이 피를 검정이나 다른 색으로 그려 상처의 현실감을 낮춘다. 실제로 벌어진 폭력과 화면에서 받는 인상이 어긋날 수 있다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003308/index.html"},{"id":"MEJE-KW-003309","row_version":2,"title":"흑인 여성 책임자라는 인물 틀","original":"Black Boss Lady","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"흑인 여성 상사가 능력과 단호함으로 조직을 이끄는 인물로 등장한다. 정체성이 단지 다양성을 표시하는 역할에 그치지 않도록 개인의 목표와 관계도 살핀다. 흑인 괴짜·전문가 인물와 마찬가지로 인종과 직업만으로 인물을 다 말하지 않는다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003309/index.html"},{"id":"MEJE-KW-003310","row_version":1,"title":"속을 모른 채 쓰는 핵심 장치","original":"Black Box","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"사람들이 내부 원리를 이해하지 못하는 장치의 결과에 사회나 임무를 의존한다. 작동이 멈췄을 때 고치거나 대체할 수 없는 상태가 갈등이 된다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-003310/index.html"},{"id":"MEJE-KW-003311","row_version":2,"title":"흑인 권투 선수를 적수로 그리는 고정관념","original":"Black Boxer Stereotype","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"권투 이야기에서 흑인 선수를 거만하고 위협적인 상대라는 틀에 넣는다. 경기의 갈등과 인종적 고정관념을 구분해 비판적으로 읽는다. 흑인 인물의 재현이라는 점에서 흑인 괴짜·전문가 인물와 함께 고정관념을 점검한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-003311/index.html"},{"id":"MEJE-KW-003312","row_version":1,"title":"검은 속옷을 성격의 암시로 쓰기","original":"Black Bra and Panties","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"검은 속옷을 보였다는 이유로 인물의 성적 의도나 위험한 성격을 암시한다. 옷의 색과 개인의 선택을 곧바로 연결하는 편견이 장면을 이끈다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-003312/index.html"},{"id":"MEJE-KW-003313","row_version":1,"title":"부정적 감정이 방으로 나타난 마음속 공간","original":"Black Bug Room","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"인물의 두려움이나 죄책감을 어두운 방으로 형상화한다. 실제 마음을 방처럼 단순화한 상징이며 그곳에서 벗어나는 과정이 회복의 이미지가 된다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-003313/index.html"},{"id":"MEJE-KW-003314","row_version":1,"title":"죽음의 선고를 알리는 검은 모자","original":"Black Cap of Death","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"과거 법정 장면에서 판사가 검은 모자를 쓰는 행동이 사형 선고의 예고로 쓰인다. 의복 하나가 인물의 운명이 바뀌는 순간을 표시한다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-003314/index.html"},{"id":"MEJE-KW-003315","row_version":1,"title":"검은 고양이가 불운을 부른다는 믿음","original":"Black Cat Luck","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"검은 고양이를 만난 뒤 나쁜 일이 생기리라 여기는 인물들이 등장한다. 동물의 실제 행동보다 사람들이 부여한 징조의 뜻이 사건을 움직인다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-003315/index.html"},{"id":"MEJE-KW-003316","row_version":2,"title":"검은 망토로 적대 세력 드러내기","original":"Black Cloak","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"얼굴을 가리는 검은 망토를 적대 인물이나 집단의 눈에 띄는 복장으로 쓴다. 같은 옷을 훔쳐 입으면 정체를 숨기는 장치로도 바뀐다. 복장 속 인물이 한 명의 적수라면 정체를 감춘 검은 갑옷의 기사가 된다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003316/index.html"},{"id":"MEJE-KW-003317","row_version":2,"title":"어두운 소재를 다루는 희극","original":"Black Comedy","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"죽음이나 폭력처럼 무거운 일을 웃음의 방식으로 다루는 이야기 유형. 웃음이 누구를 향하는지에 따라 장면의 의미와 불편함이 달라진다. 피해가 웃음으로 소비되는 경우로 동물 학대를 웃음으로 처리하기가 있다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-003317/index.html"},{"id":"MEJE-KW-003318","row_version":2,"title":"동물 학대를 웃음으로 처리하기","original":"Black Comedy Animal Cruelty","aliases":[],"kind":"keyword","facet_id":"ML-F19","node_kind":null,"parent_id":null,"tag_path":["ML-F19"],"summary":"작품이 동물이 겪는 해를 농담이나 가벼운 소동으로 넘긴다. 피해가 장면에서 지워지는지 살피는 것이 웃음의 방향을 판단하는 데 중요하다. 어두운 소재를 다루는 희극 안에서도 피해의 대상을 지우는 방식은 따로 살핀다.","accent":"#9B7F74","tab":"#9A6A55","facet":"정서·톤","bookmark":"분류축","entry_url":"cards/MEJE-KW-003318/index.html"},{"id":"MEJE-KW-003319","row_version":2,"title":"가벼운 작품에 끼어든 한순간의 어두운 농담","original":"Black Comedy Burst","aliases":[],"kind":"keyword","facet_id":"ML-F19","node_kind":null,"parent_id":null,"tag_path":["ML-F19"],"summary":"평소 밝은 이야기가 잠깐 무거운 소재를 가볍게 말하고 곧 원래 분위기로 돌아간다. 한 장면의 웃음이 전체 작품의 정서와 어긋나며 기억에 남는다. 한 장면만 어두운 소재를 다루는 희극의 어조로 바뀌는 경우다.","accent":"#9B7F74","tab":"#9A6A55","facet":"정서·톤","bookmark":"분류축","entry_url":"cards/MEJE-KW-003319/index.html"},{"id":"MEJE-KW-003320","row_version":2,"title":"인육 식사를 어두운 농담으로 쓰기","original":"Black Comedy Cannibalism","aliases":[],"kind":"keyword","facet_id":"ML-F19","node_kind":null,"parent_id":null,"tag_path":["ML-F19"],"summary":"사람을 먹는 금기를 실제 장면이나 암시로 제시해 불편한 웃음을 만든다. 행위의 자세한 묘사보다 누가 위험을 농담으로 받아들이는지가 핵심이다. 금기를 농담으로 다룬다는 점에서 어두운 소재를 다루는 희극의 한 방식이다.","accent":"#9B7F74","tab":"#9A6A55","facet":"정서·톤","bookmark":"분류축","entry_url":"cards/MEJE-KW-003320/index.html"},{"id":"MEJE-KW-003321","row_version":2,"title":"아동 대상 성적 가해를 농담으로 쓰기","original":"Black Comedy Pedophilia","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"작품이 아동을 향한 성적 가해의 암시를 어두운 농담으로 처리한다. 웃음의 대상과 피해 아동의 존재가 지워지는 방식을 비판적으로 살핀다. 어두운 소재를 다루는 희극의 이름으로 피해를 가볍게 만들지 않는지 살펴야 한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-003321/index.html"},{"id":"MEJE-KW-003322","row_version":2,"title":"반려동물의 죽음을 블랙코미디로 다루기","original":"Black Comedy Pet Death","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"반려동물의 죽음이나 그 뒤의 반응을 씁쓸한 웃음으로 표현한다. 동물을 잃은 사람의 슬픔과 장면의 농담이 어떻게 충돌하는지 본다. 상실을 웃음으로 놓는 어두운 소재를 다루는 희극의 장면이다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-003322/index.html"},{"id":"MEJE-KW-003323","row_version":2,"title":"포식 장면을 어두운 농담으로 쓰기","original":"Black Comedy Predation","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"잡아먹히는 위협을 긴장보다 씁쓸한 웃음으로 보여 준다. 포식의 자연스러움과 피해자의 공포가 장면에서 다르게 읽힐 수 있다. 공포를 희극으로 바꿀 때 어두운 소재를 다루는 희극의 어조가 생긴다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-003323/index.html"},{"id":"MEJE-KW-003324","row_version":2,"title":"성폭력을 블랙코미디로 소비하기","original":"Black Comedy Rape","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"성폭력이나 그 위협을 농담의 재료로 삼는 연출. 피해의 경험을 가볍게 만들거나 피해자를 웃음거리로 두는지 비판적으로 읽는다. 어두운 소재를 다루는 희극의 장르 설명과 별개로 피해의 재현을 비판적으로 본다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-003324/index.html"},{"id":"MEJE-KW-003325","row_version":2,"title":"검은 점으로 그린 눈동자","original":"Black Dot Pupils","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"눈동자를 작은 검은 점으로 단순화해 인물의 얼굴을 그린다. 선이 적어도 위치와 움직임만으로 시선의 방향을 표현할 수 있다. 검은 점으로 그린 눈가 눈 전체를 줄인다면 이 표현은 눈동자를 점으로 줄인다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003325/index.html"},{"id":"MEJE-KW-003326","row_version":2,"title":"흑인 인물이 먼저 희생되는 관습","original":"Black Dude Dies First","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"위험한 상황에서 흑인 인물을 초반의 희생자로 배치한다. 그 인물에게 충분한 역할을 주었는지와 희생이 다른 인물의 이야기만 돕는지 살핀다. 흑인 인물의 재현을 살필 때 흑인 분장 관습의 재현의 오래된 이미지도 구분해야 한다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-003326/index.html"},{"id":"MEJE-KW-003327","row_version":2,"title":"흰자위가 검은 위험한 눈","original":"Black Eyes of Crazy","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"눈의 흰자위를 검게 그려 인물이 통제를 잃었거나 위협적이라는 인상을 만든다. 눈의 색을 실제 성격이나 정신 상태의 증거로 받아들이지는 않는다. 흰자위만 바뀌는 표현과 눈 전체가 검게 변하는 악역 표현는 시각적 범위가 다르다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003327/index.html"},{"id":"MEJE-KW-003328","row_version":2,"title":"눈 전체가 검게 변하는 악역 표현","original":"Black Eyes of Evil","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"인물이 지배당하거나 적대적으로 변한 순간 눈 전체를 검게 표현한다. 변화를 빠르게 알리는 시각 기호이며 개별 인물의 동기는 별도로 설명돼야 한다. 흰자위가 검은 위험한 눈보다 눈 전체의 변화가 크다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003328/index.html"},{"id":"MEJE-KW-003329","row_version":2,"title":"흑인 분장 관습의 재현","original":"Blackface","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"흑인을 희화화하던 과거의 분장 양식이 작품에 등장하거나 인용된다. 인종적 고정관념의 역사와 현재 장면이 그것을 비판하는 방식을 함께 살핀다. 그 분장 양식이 그림으로 남으면 흑인 분장을 닮은 만화 캐리커처가 된다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-003329/index.html"},{"id":"MEJE-KW-003330","row_version":2,"title":"흑인 분장을 닮은 만화 캐리커처","original":"Blackface-Style Caricature","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"짙은 피부와 과장된 입술·눈을 조합한 옛 만화 그림체. 인종차별적 이미지에서 비롯된 형태가 새로운 캐릭터 디자인에 남아 있는지 검토한다. 그림 속 흔적의 배경에는 흑인 분장 관습의 재현의 역사가 있다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003330/index.html"},{"id":"MEJE-KW-003331","row_version":1,"title":"흑인 여성과 백인 남성의 연애를 둘러싼 갈등","original":"Black Gal on White Guy Drama","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"두 사람의 관계에 주변의 인종적 편견과 가족의 기대가 끼어든다. 당사자의 실제 선택과 타인이 관계에 덧씌운 해석을 구분한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003331/index.html"},{"id":"MEJE-KW-003332","row_version":2,"title":"검은 빈 화면을 배경으로 쓰기","original":"Blackground","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임이 세밀한 풍경 대신 비어 있는 검은 배경을 의도적으로 택한다. 어둠과 고립감 또는 화면 속 대상의 가독성을 조절하는 공간 표현이다. 빛이 사라지는 시간까지 조작하면 불이 꺼졌다 켜지는 게임 구역가 된다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-003332/index.html"},{"id":"MEJE-KW-003333","row_version":1,"title":"비밀 조직의 검은 헬리콥터","original":"Black Helicopter","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"검은 헬리콥터가 도착해 은밀한 정부 조직이나 추적자의 존재를 알린다. 기체의 색과 갑작스러운 등장이 감시의 분위기를 만든다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-003333/index.html"},{"id":"MEJE-KW-003334","row_version":1,"title":"무엇이든 즉시 삼키는 배","original":"Black-Hole Belly","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"생물이 자기 몸보다 큰 물체도 삼킨 뒤 아무 변화 없이 움직인다. 배 안의 크기와 소화에 관한 현실의 규칙을 벗어난 허구의 몸이다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-003334/index.html"},{"id":"MEJE-KW-003335","row_version":1,"title":"한 인물에게 모든 이야기가 휘는 현상","original":"Black Hole Sue","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"주변 인물의 선택과 사건의 우연이 유독 한 인물을 돋보이게 하는 방향으로 반복된다. 그 결과 다른 인물의 동기와 세계의 독립성이 약해질 수 있다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-003335/index.html"},{"id":"MEJE-KW-003336","row_version":2,"title":"흑인 남성의 성적 능력에 관한 고정관념","original":"Black Is Bigger in Bed","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"작품이 흑인 남성의 몸이나 친밀한 관계의 능력을 인종만으로 예단한다. 칭찬처럼 보여도 한 사람을 몸의 이미지로 환원하는 편견이다. 성별이 다른 흑인 인물을 다뤄도 흑인 여성을 성적 대상으로만 그리기처럼 몸만 남기는 환원은 같다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-003336/index.html"},{"id":"MEJE-KW-003337","row_version":2,"title":"흑인 여성을 성적 대상으로만 그리기","original":"Black Jezebel Stereotype","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"흑인 여성 인물에게 독립적인 동기보다 남의 욕망을 채우는 역할만 반복해서 준다. 인물의 선택과 삶이 화면에서 얼마나 허용되는지 살핀다. 흑인 남성의 성적 능력에 관한 고정관념와 함께 인종과 성별에 대한 성적 고정관념을 점검한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003337/index.html"},{"id":"MEJE-KW-003338","row_version":2,"title":"정체를 감춘 검은 갑옷의 기사","original":"Black Knight","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"얼굴을 드러내지 않는 검은 갑옷의 기사가 강한 적수로 등장한다. 그가 누구인지 알 수 없다는 점이 전투 못지않게 갈등을 이끈다. 한 인물의 복장이 집단의 표지가 되면 검은 망토로 적대 세력 드러내기의 인상과 닿는다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003338/index.html"},{"id":"MEJE-KW-003339","row_version":2,"title":"다른 집단의 사람으로 위장해 차별을 겪기","original":"Black Like Me","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 다른 사회 집단에 속한 것처럼 위장한 뒤 이전과 다른 대우를 받는다. 잠시 겪은 일이 그 집단의 삶 전체를 이해한 증거가 되지는 않는다. 편견을 겪는 관계는 흑인 여성과 백인 남성의 연애를 둘러싼 갈등의 주변 갈등과 연결될 수 있다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-003339/index.html"},{"id":"MEJE-KW-003340","row_version":1,"title":"공격 마법에 특화된 마법사","original":"Black Mage","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"마법으로 직접 공격하거나 넓은 범위에 힘을 쓰는 역할을 맡는다. 치유나 지원을 담당하는 마법사와의 역할 구분이 집단의 전술을 만든다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-003340/index.html"},{"id":"MEJE-KW-003341","row_version":2,"title":"비밀을 빌미로 요구하기","original":"Blackmail","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"한 인물이 타인이 감추려는 사실을 공개하겠다며 돈이나 행동을 요구한다. 비밀 자체보다 공개의 두려움을 힘으로 바꾼 관계다. 공개를 두려워하지 않는 상대라면 협박이 협박자에게 되돌아오기이 일어난다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003341/index.html"},{"id":"MEJE-KW-003342","row_version":2,"title":"협박이 협박자에게 되돌아오기","original":"Blackmail Backfire","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"비밀을 이용해 상대를 움직이려 했지만 상대가 공개를 두려워하지 않거나 더 큰 반격에 나선다. 협박자가 잘못 읽은 힘의 관계가 뒤집힌다. 상대의 두려움을 잘못 짚은 비밀을 빌미로 요구하기의 실패다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003342/index.html"},{"id":"MEJE-KW-003343","row_version":2,"title":"협박을 점잖은 말로 포장하기","original":"\"Blackmail\" Is Such an Ugly Word","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 명백한 협박을 보험이나 협조처럼 부드러운 말로 바꿔 부른다. 행동을 인정하면서 이름만 피하는 태도가 권력과 뻔뻔함을 드러낸다. 부드러운 말로 꾸며도 요구의 구조는 비밀을 빌미로 요구하기와 같다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-003343/index.html"},{"id":"MEJE-KW-003344","row_version":2,"title":"금지된 물품이 거래되는 비공식 시장","original":"Black Market","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"공식 제도 밖에서 금지되거나 구하기 어려운 물건과 서비스가 거래된다. 무엇이 금지됐고 누가 거래를 묵인하는지가 세계의 권력 구조를 보여 준다. 음식까지 비밀 거래의 대상이 되면 암시장에서만 구할 수 있는 신선한 음식가 나타난다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-003344/index.html"},{"id":"MEJE-KW-003345","row_version":2,"title":"암시장에서만 구할 수 있는 신선한 음식","original":"Black Market Produce","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"평범한 식품이 귀해진 사회에서 과일이나 고기 같은 음식이 비밀 거래의 사치품이 된다. 음식의 맛과 향이 결핍된 일상을 선명하게 드러낸다. 평범한 음식을 얻는 통로가 금지된 물품이 거래되는 비공식 시장뿐인 사회다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-003345/index.html"},{"id":"MEJE-KW-003346","row_version":1,"title":"블랙 메탈 음악","original":"Black Metal","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":null,"parent_id":null,"tag_path":["ML-F02"],"summary":"거친 음향과 어두운 분위기를 중심에 둔 극단적 헤비메탈 계열의 음악. 작품 속 사용에서는 음악의 소리와 그 장면이 부여한 이미지를 구분한다.","accent":"#55758A","tab":"#9A6A55","facet":"미디어","bookmark":"분류축","entry_url":"cards/MEJE-KW-003346/index.html"},{"id":"MEJE-KW-003347","row_version":2,"title":"불이 꺼졌다 켜지는 게임 구역","original":"Blackout Basement","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임 구역의 조명이 반복해서 사라지거나 플레이어의 행동에 따라 돌아온다. 보이는 시간과 보이지 않는 시간이 이동과 탐색의 규칙이 된다. 조명이 꺼진 순간 검은 빈 화면을 배경으로 쓰기의 화면 인상이 강해진다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-003347/index.html"},{"id":"MEJE-KW-003348","row_version":2,"title":"집단의 예상과 다른 정치 성향을 지닌 흑인 인물","original":"Black Republican","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"미국 정치 이야기에서 흑인 인물이 공화당을 지지해 주변 인물과 의견이 부딪힌다. 인종만으로 한 사람의 정치적 선택을 단정하는 시선을 드러낸다. 정치 선택을 인종으로 단정하지 않는다는 점에서 흑인 괴짜·전문가 인물와 함께 본다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003348/index.html"},{"id":"MEJE-KW-003349","row_version":1,"title":"검은 화면 뒤에 결과 보여주기","original":"Black Screen of Death","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"두 인물이 충돌하는 순간 화면을 검게 가리고 결과만 나중에 보여 준다. 보이지 않은 짧은 시간에 무슨 일이 있었는지가 긴장과 웃음을 만든다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-003349/index.html"},{"id":"MEJE-KW-003350","row_version":2,"title":"집단에서 배척당하는 가족 구성원","original":"Black Sheep","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"가족이나 무리의 기준에 맞지 않는다는 이유로 한 사람이 밖으로 밀려난다. 차이를 가진 사람의 선택과 집단의 배제 방식을 함께 본다. 새로운 가족에서도 한 인물이 계속 배제된다면 두 가족이 합쳐지며 겪는 변화의 갈등과 겹친다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003350/index.html"},{"id":"MEJE-KW-003351","row_version":1,"title":"기존 음악과 다른 곡이 대표곡 되기","original":"Black Sheep Hit","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"음악가의 평소 스타일과 다른 곡이 가장 널리 알려진다. 성공한 노래와 창작자가 지키려던 정체성 사이에 간극이 생긴다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-003351/index.html"},{"id":"MEJE-KW-003352","row_version":1,"title":"극단주의에 합류할 날을 기다리는 사람","original":"Black Shirt","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"일상에서는 불만을 쌓던 인물이 권위주의 세력이 등장하자 적극적으로 가담한다. 폭력적인 체제는 준비된 추종자의 선택으로 힘을 얻는다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-003352/index.html"},{"id":"MEJE-KW-003353","row_version":1,"title":"흑인 인물이 중심인 상황극","original":"Black Sitcom","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":null,"parent_id":null,"tag_path":["ML-F02"],"summary":"흑인 인물과 공동체의 일상을 주요 인물과 이야기로 삼는 상황극의 범주. 인물들의 삶과 유머를 하나의 경험으로 단순화하지 않는다.","accent":"#55758A","tab":"#9A6A55","facet":"미디어","bookmark":"분류축","entry_url":"cards/MEJE-KW-003353/index.html"},{"id":"MEJE-KW-003354","row_version":1,"title":"존재를 숨긴 비밀 시설","original":"Black Site","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"정부나 큰 조직이 시설의 위치와 실제 용도를 감춘다. 겉으로 공개한 기능과 안에서 벌어지는 일이 다를 수 있다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-003354/index.html"},{"id":"MEJE-KW-003355","row_version":1,"title":"대장장이가 장비를 고쳐 주기","original":"Blacksmith Upgrade Service","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임 속 대장장이에게 무기나 방어구를 맡겨 수리하거나 성능을 높인다. 비용과 재료가 다음 탐험의 선택을 만든다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-003355/index.html"},{"id":"MEJE-KW-003356","row_version":1,"title":"불길하게 들리는 초월자의 언어","original":"Black Speech","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"초월적 존재가 말을 할 때 소리와 의미가 듣는 이에게 낯선 위협으로 느껴진다. 언어 자체의 본질보다 장면이 만든 감각을 구분한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-003356/index.html"},{"id":"MEJE-KW-003357","row_version":1,"title":"표식으로 전달되는 죽음의 경고","original":"Black Spot","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"과거의 적이 상징적인 물건이나 문양을 보내 인물에게 다가올 보복을 알린다. 메시지가 짧을수록 받는 사람의 기억이 공포를 채운다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-003357/index.html"},{"id":"MEJE-KW-003358","row_version":1,"title":"검은 칼날이 힘을 상징하기","original":"Black Swords Are Better","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"검은 색의 칼을 등장시켜 특별한 힘이나 위험한 기원을 암시한다. 색만으로 무기의 실제 성질이나 사용자의 선악은 결정되지 않는다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-003358/index.html"},{"id":"MEJE-KW-003359","row_version":2,"title":"격식 있는 행사에 손님으로 잠입하기","original":"Black-Tie Infiltration","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 초대받은 손님처럼 차려입고 엄격한 경비가 있는 행사에 들어간다. 화려한 공개 공간이 오히려 정체를 숨기는 장소가 된다. 격식 있는 행사에 섞여 행동한다는 점에서 군중 속 한 사람처럼 섞여 숨기의 잠입 규칙과 통한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003359/index.html"},{"id":"MEJE-KW-003360","row_version":1,"title":"시대극에서 예상과 다른 인종 배역","original":"Black Vikings","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"시대극의 인물에 관객의 통념과 다른 인종적 배경의 배우가 캐스팅된다. 작품의 설정과 실제 역사, 무대의 표현 관습을 각각 확인하며 해석한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-003360/index.html"},{"id":"MEJE-KW-003361","row_version":1,"title":"배우자를 반복해서 해치는 결혼 사기범","original":"Black Widow","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"결혼이나 연애 관계를 이용해 상대의 재산을 노리고 해치는 인물. 성별 고정관념보다 반복되는 사기와 폭력의 선택에 초점을 둔다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003361/index.html"},{"id":"MEJE-KW-003362","row_version":1,"title":"검은 늑대에 위험을 투사하기","original":"Black Wolves Are Deadlier","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"검은 털의 늑대를 다른 색의 늑대보다 위험하게 보이도록 그린다. 털색에서 성격을 읽는 것은 작품의 시각적 약속이다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-003362/index.html"},{"id":"MEJE-KW-003363","row_version":1,"title":"쉬지 못하게 하는 게임 저장 규칙","original":"Bladder of Steel","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"저장 지점이 멀거나 일시정지가 제한되어 플레이어가 중간에 쉬기 어렵다. 도전의 설계가 실제 플레이 시간에 주는 부담도 함께 본다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-003363/index.html"},{"id":"MEJE-KW-003364","row_version":2,"title":"팔에 붙은 칼날","original":"Blade Below the Shoulder","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"칼날이 팔에 달리거나 팔의 일부를 대신해 전투 중에 펼쳐진다. 무기가 몸과 분리되지 않는 만큼 일상적인 움직임도 달라진다. 팔 대신 신발에 칼날을 숨긴 형태로 칼날을 숨긴 신발이 있다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-003364/index.html"},{"id":"MEJE-KW-003365","row_version":2,"title":"칼날을 박아 움직임 멈추기","original":"Blade Brake","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"빠르게 밀려가던 인물이 칼날을 바닥이나 벽에 대어 속도를 줄인다. 표면에 남은 자국이 움직임의 힘을 시각화한다. 칼날을 이동의 지지대로 쓰는 장면은 상대의 칼날 위를 달리기에서도 과장된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003365/index.html"},{"id":"MEJE-KW-003366","row_version":1,"title":"칼날 무기를 수집하는 인물","original":"Blade Enthusiast","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 형태와 제작법이 다른 칼날 무기에 깊은 관심을 보인다. 수집의 이유가 기술적 호기심인지 권력의 욕망인지에 따라 인상이 달라진다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-003366/index.html"},{"id":"MEJE-KW-003367","row_version":1,"title":"칼날을 숨긴 신발","original":"Blade Footwear","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"신발에 숨겨진 칼날이 가까운 거리의 뜻밖의 위협이 된다. 눈에 띄지 않는 물건을 전투 도구로 바꾸는 소품이다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-003367/index.html"},{"id":"MEJE-KW-003368","row_version":2,"title":"칼을 맞대고 힘겨루기","original":"Blade Lock","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"서로의 칼날이 엇갈린 채 두 인물이 가까운 거리에서 버틴다. 움직임이 잠시 멈추며 표정과 대사가 충돌을 이어 간다. 맞댄 칼을 움직임의 발판으로 바꾸면 상대의 칼날 위를 달리기의 구도가 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003368/index.html"},{"id":"MEJE-KW-003369","row_version":1,"title":"사물의 작은 세부로 시선 돌리기","original":"Blade-of-Grass Cut","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"큰 사건 중간에 풀잎이나 장난감 같은 고요한 사물을 가까이 보여 준다. 직접 보이지 않는 인물의 감정이 시선의 이동으로 드러난다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-003369/index.html"},{"id":"MEJE-KW-003370","row_version":1,"title":"줄에 매단 칼날 무기","original":"Blade on a Rope","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"줄이나 사슬 끝에 칼날을 달아 먼 거리와 가까운 거리 모두에서 움직인다. 무기의 궤도가 장면의 공간을 넓힌다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-003370/index.html"},{"id":"MEJE-KW-003371","row_version":1,"title":"칼날에 비친 얼굴","original":"Blade Reflection","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물의 얼굴이나 상대의 모습이 잘 닦인 칼날에 비친다. 한 화면 안에 무기와 시선의 대상을 함께 넣는 구도다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-003371/index.html"},{"id":"MEJE-KW-003372","row_version":2,"title":"상대의 칼날 위를 달리기","original":"Blade Run","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"인물이 상대가 내민 큰 칼 위에 올라 빠르게 접근한다. 현실의 균형보다 과장된 운동감과 우위를 드러내는 장면이다. 칼날을 지지대로 삼는 또 다른 장면으로 칼날을 박아 움직임 멈추기가 있다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003372/index.html"},{"id":"MEJE-KW-003373","row_version":1,"title":"칼날로 연속 공격하기","original":"Blade Spam","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 칼이나 발톱으로 빠른 공격을 여러 번 이어 간다. 한 번의 큰 타격 대신 속도와 반복으로 압박한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003373/index.html"},{"id":"MEJE-KW-003374","row_version":1,"title":"말소리가 의미 없는 중얼거림으로 들리기","original":"Blah, Blah, Blah","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"한 인물이 듣는 말이 알아들을 수 없는 반복음처럼 처리된다. 설명을 듣지 못하거나 듣고 싶지 않은 심리를 소리로 드러낸다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-003374/index.html"},{"id":"MEJE-KW-003375","row_version":1,"title":"강제된 게임 선택을 플레이어 탓하기","original":"Blamed for Being Railroaded","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임이 다른 선택지를 주지 않고 어떤 행동을 시킨 뒤 그 결과를 플레이어의 책임이라고 말한다. 선택할 수 있었던 범위와 서사의 비난이 어긋난다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-003375/index.html"},{"id":"MEJE-KW-003376","row_version":2,"title":"실패 뒤 서로에게 책임 떠넘기기","original":"Blame Game","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"같은 실패에 관여한 사람들이 자기 몫을 인정하지 않고 상대에게 잘못을 돌린다. 책임의 위치보다 관계의 균열이 먼저 드러난다. 책임을 떠넘기는 상대가 조언자라면 조언을 따르고 조언자 탓하기의 형태가 된다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003376/index.html"},{"id":"MEJE-KW-003377","row_version":1,"title":"외도 상대에게만 분노 돌리기","original":"Blame the Paramour","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"연인의 외도를 알게 된 인물이 약속을 어긴 연인보다 제삼자를 더 강하게 탓한다. 분노의 방향이 친밀한 상대와의 대면을 피하는 방식일 수 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003377/index.html"},{"id":"MEJE-KW-003378","row_version":2,"title":"조언을 따르고 조언자 탓하기","original":"Blaming the Advisor","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 남의 조언을 자기 판단으로 받아들인 뒤 결과가 나쁘자 조언자에게만 책임을 돌린다. 조언의 질과 실행을 선택한 책임을 분리해 본다. 도구가 아니라 조언자를 탓한다는 점에서 실수의 원인을 도구에만 돌리기와 변명의 대상이 다르다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-003378/index.html"},{"id":"MEJE-KW-003379","row_version":2,"title":"외도당한 사람에게 책임 돌리기","original":"Blaming the Cuckold","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"관계의 약속을 어긴 사람이 상처받은 상대의 부족함을 이유로 자신의 행동을 정당화한다. 책임 전가가 피해자의 자기 인식까지 흔들 수 있다. 외도의 책임을 다른 곳으로 보내는 방식은 외도 상대에게만 분노 돌리기에도 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003379/index.html"},{"id":"MEJE-KW-003380","row_version":1,"title":"모호한 지배 세력 탓하기","original":"Blaming \"The Man\"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"인물이 사회 문제의 원인을 이름과 범위가 불분명한 권력 집단으로 설명한다. 실제 제도를 짚는 비판과 막연한 음모의 언어를 구분한다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-003380/index.html"},{"id":"MEJE-KW-003381","row_version":2,"title":"실수의 원인을 도구에만 돌리기","original":"Blaming the Tools","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 결과가 나쁠 때 자신의 기술이나 판단보다 장비의 결함을 먼저 탓한다. 실제 장비의 문제와 변명을 가를 단서가 필요하다. 실행의 책임을 바깥으로 옮기는 또 다른 방식으로 조언을 따르고 조언자 탓하기가 있다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-003381/index.html"},{"id":"MEJE-KW-003382","row_version":2,"title":"피해자에게 피해의 책임 묻기","original":"Blaming the Victim","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"가해자의 행동 대신 피해자의 선택을 문제 삼아 책임을 옮긴다. 사건의 원인과 사후 대처를 혼동하면 가해의 책임이 흐려진다. 외도를 당한 사람에게 책임을 옮기는 외도당한 사람에게 책임 돌리기는 이 판단의 한 형태다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-003382/index.html"},{"id":"MEJE-KW-003383","row_version":1,"title":"실제 상표를 살짝 바꾼 가상 제품","original":"Bland-Name Product","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"널리 알려진 상품의 이름이나 모양을 조금 바꿔 작품 속 제품으로 쓴다. 익숙함을 남기면서도 허구 세계의 독립된 물건처럼 보이게 한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-003383/index.html"},{"id":"MEJE-KW-003384","row_version":1,"title":"내용이 비어 있는 책","original":"Blank Book","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"인물이 펼친 책에 기대한 글이 없거나 같은 글자가 반복된다. 책의 빈자리가 세계의 이상이나 속임수의 단서가 된다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-003384/index.html"},{"id":"MEJE-KW-003385","row_version":1,"title":"담요와 베개로 만든 비밀 공간","original":"Blanket Fort","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"담요와 쿠션을 겹쳐 작은 임시 방을 만든다. 허술한 구조도 그 안에서는 놀이와 대화의 안전한 경계가 된다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-003385/index.html"},{"id":"MEJE-KW-003386","row_version":1,"title":"한 이불을 서로 끌어당기기","original":"Blanket Tug O' War","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"함께 자는 두 사람이 잠결에 이불을 자기 쪽으로 끌어당긴다. 작은 몸짓이 친밀함과 사소한 불편을 동시에 보여 준다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003386/index.html"},{"id":"MEJE-KW-003387","row_version":1,"title":"경험과 신념이 없는 빈 인물","original":"Blank Slate","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"기억이나 삶의 경험이 거의 없이 만들어진 인물이 주변의 말에 따라 자신을 구성한다. 빈 상태를 성장의 가능성뿐 아니라 조종당할 위험으로도 본다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003387/index.html"},{"id":"MEJE-KW-003388","row_version":2,"title":"아무 반응 없는 멍한 시선","original":"Blank Stare","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"인물이 상대의 말이나 사건에 한동안 표정을 바꾸지 않고 바라본다. 감정이 없는지 표현을 미루는지는 장면의 맥락에서 드러난다. 시선의 감정 표현을 더 과장하면 눈동자가 사라진 흰 눈처럼 눈의 모양 자체가 달라진다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003388/index.html"},{"id":"MEJE-KW-003389","row_version":2,"title":"눈동자가 사라진 흰 눈","original":"Blank White Eyes","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"인물의 눈을 흰 원으로 단순화해 큰 충격이나 실신을 표현한다. 실제 신체 상태보다 만화적 감정 기호에 가깝다. 아무 반응 없는 멍한 시선보다 그림의 변화가 크지만 반응을 짧게 보여 준다는 점은 같다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003389/index.html"},{"id":"MEJE-KW-003390","row_version":1,"title":"끝없이 펼쳐진 흰 공간","original":"Blank White Void","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"벽과 수평선이 보이지 않는 하얀 공간에 인물이 놓인다. 비어 있는 풍경이 감금이나 사유, 세계 사이의 경계를 표현한다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-003390/index.html"},{"id":"MEJE-KW-003391","row_version":2,"title":"신보다 자신이 높다고 주장하기","original":"Blasphemous Boast","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 신성한 존재보다 자신이 뛰어나다고 선언한다. 그 말이 허세인지 실제 힘의 고백인지에 따라 주변의 반응이 달라진다. 자신을 높이는 말과 타인을 높이는 사람을 신에 빗대어 찬양하기의 화자를 구분한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-003391/index.html"},{"id":"MEJE-KW-003392","row_version":2,"title":"사람을 신에 빗대어 찬양하기","original":"Blasphemous Praise","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"누군가를 찬양하면서 신성한 존재와 비교한다. 듣는 사람의 믿음과 관계에 따라 칭찬이 부담이나 모욕이 될 수도 있다. 말하는 사람이 자기 자신을 신과 비교하면 신보다 자신이 높다고 주장하기가 된다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-003392/index.html"},{"id":"MEJE-KW-003393","row_version":2,"title":"상대 손의 무기를 쏘아 떨어뜨리기","original":"Blasting It Out of Their Hands","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"총격으로 상대가 든 무기를 떨어뜨려 싸움을 멈춘다. 치명적 공격을 피하려는 의도와 장면의 과장된 정확도를 구분한다. 무기만 떨어뜨리려던 장면이 통제를 잃으면 한 발 뒤에 모두가 총을 쏘기으로 번질 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003393/index.html"},{"id":"MEJE-KW-003394","row_version":1,"title":"힘을 모아 크게 발사하기","original":"Blasting Time","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"인물이 팔과 몸을 크게 움직이며 에너지를 모았다가 한 번에 내보낸다. 발사 전의 자세가 공격의 규모를 예고한다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003394/index.html"},{"id":"MEJE-KW-003395","row_version":2,"title":"한 발 뒤에 모두가 총을 쏘기","original":"Blast Out","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"무장한 사람들이 팽팽히 대치하다 첫 총성이 나자 한꺼번에 사격한다. 누가 시작했는지보다 통제력을 잃은 집단의 반응이 장면을 지배한다. 일제 사격 대신 무장을 막는 한 발에 집중하면 상대 손의 무기를 쏘아 떨어뜨리기와 방향이 달라진다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003395/index.html"},{"id":"MEJE-KW-003396","row_version":1,"title":"담담하게 자기 힘 자랑하기","original":"Blasé Boast","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 놀랄 만한 능력을 평범한 사실처럼 말한다. 과장하지 않는 어조가 오히려 힘의 차이를 강조한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-003396/index.html"}]}.cards;